BEGIN;
create temp table checks(label text);
create function pg_temp.check(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;insert into checks values(label);end$$;
create temp table fixture(property_id uuid,actor_id uuid);
insert into fixture select gen_random_uuid(),id from public.profiles where org_id='22222222-2222-2222-2222-222222222222' and role='admin' limit 1;
insert into public.properties(id,org_id,name)select property_id,'22222222-2222-2222-2222-222222222222','Brand research SQL fixture' from fixture;
DO $$declare p uuid;actor uuid;q uuid:=gen_random_uuid();c jsonb;r jsonb;decision uuid:=gen_random_uuid();input jsonb:='{"mode":"saved","radiusMiles":3,"maxCompetitors":10}';output jsonb:='{"competitors":[],"marketGaps":[],"evidence":{"current":0,"stale":0,"unverified":0},"provider":{"discovery":"not_requested","intelligence":"not_requested"}}';
begin
 select property_id,actor_id into p,actor from fixture;
 c:=public.begin_brand_research(p,actor,q,input);
 perform pg_temp.check(c->>'state'='claimed','research has one owner');
 perform pg_temp.check(public.check_brand_research(q,(c->>'claimToken')::uuid)->>'state'='active','current owner may call provider');
 perform pg_temp.check(public.begin_brand_research(p,actor,q,input)->>'state'='running','same unfinished request cannot redispatch');
 perform pg_temp.check(public.begin_brand_research(p,actor,q,input||'{"radiusMiles":4}')->>'state'='request_conflict','settings cannot change under saved identity');
 perform pg_temp.check(public.begin_brand_research(p,actor,gen_random_uuid(),input)->>'state'='busy','overlapping research held');
 perform pg_temp.check(public.begin_brand_research(p,gen_random_uuid(),gen_random_uuid(),input)->>'state'='forbidden','unknown actor rejected');
 perform pg_temp.check(public.finish_brand_research(q,gen_random_uuid(),output)->>'state'='claim_conflict','forged claim rejected');
 r:=public.finish_brand_research(q,(c->>'claimToken')::uuid,output);
 perform pg_temp.check(r->>'state'='applied','snapshot and outcome save');
 perform pg_temp.check(public.begin_brand_research(p,actor,q,input)->>'state'='replayed','lost response recovers exact snapshot');
 perform pg_temp.check(public.finish_brand_research(q,(c->>'claimToken')::uuid,output)->>'state'='replayed','duplicate finalization returns saved result');
 perform pg_temp.check((select count(*)=2 from public.shared_action_events where episode_id=q),'one request and one completion event');
 perform pg_temp.check((select result=output and state='succeeded' from public.brand_research_runs where id=q),'private snapshot is the saved source');
 perform pg_temp.check((select not training_eligible and after_state->>'competitorCount'='0' from public.shared_action_events where id=q),'history is an attributed summary excluded from training');
 begin update public.brand_research_runs set result='{}' where id=q;raise exception 'FAIL mutable research';exception when raise_exception then if SQLERRM<>'Research history is immutable' then raise;end if;end;
 perform pg_temp.check((select result=output from public.brand_research_runs where id=q),'finished evidence cannot be rewritten');
 q:=gen_random_uuid();c:=public.begin_brand_research(p,actor,q,input);
 perform pg_temp.check(public.cancel_brand_research(p,q,actor,decision)->>'state'='cancelled','operator can stop an unfinished report');
 perform pg_temp.check(public.cancel_brand_research(p,q,actor,decision)->>'state'='cancelled','lost stop acknowledgment replays');
 perform pg_temp.check(public.cancel_brand_research(p,gen_random_uuid(),actor,decision)->>'state'='request_conflict','stop identity cannot target another report');
 perform pg_temp.check(public.check_brand_research(q,(c->>'claimToken')::uuid)->>'state'='cancelled','stop fences new provider steps');
 perform pg_temp.check(public.finish_brand_research(q,(c->>'claimToken')::uuid,output)->>'state'='cancelled','late result cannot overwrite stop');
 perform pg_temp.check((select result->>'providerStopConfirmed'='false' from public.shared_action_events where id=decision),'local stop does not pretend provider cancellation');
 q:=gen_random_uuid();c:=public.begin_brand_research(p,actor,q,input);
 r:=public.finish_brand_research(q,(c->>'claimToken')::uuid,'{"provider":{"discovery":"completed","intelligence":"unknown"}}','research_failed');
 perform pg_temp.check(r->>'state'='failed','failure saved distinctly');
 perform pg_temp.check((select result->'provider'->>'intelligence'='unknown' from public.brand_research_runs where id=q),'failure retains uncertain provider evidence');
 perform pg_temp.check(public.begin_brand_research(p,actor,q,input)->>'state'='failed','same failed identity does not dispatch twice');
 perform pg_temp.check(not has_table_privilege('authenticated','public.brand_research_runs','select'),'private claims unavailable to browser');
 perform pg_temp.check(not has_function_privilege('authenticated','public.begin_brand_research(uuid,uuid,uuid,jsonb)','execute'),'research commands service-only');
end$$;
create function pg_temp.reject_research_event() returns trigger language plpgsql as $$begin if new.action='brand.research.completed' then raise exception 'History unavailable';end if;return new;end$$;
create trigger research_fixture_history_failure before insert on public.shared_action_events for each row execute function pg_temp.reject_research_event();
DO $$declare p uuid;actor uuid;q uuid:=gen_random_uuid();c jsonb;
begin
 select property_id,actor_id into p,actor from fixture;
 c:=public.begin_brand_research(p,actor,q,'{"mode":"saved","radiusMiles":3,"maxCompetitors":10}');
 begin perform public.finish_brand_research(q,(c->>'claimToken')::uuid,'{"competitors":[],"marketGaps":[],"evidence":{}}');raise exception 'FAIL saved without history';exception when raise_exception then if SQLERRM<>'History unavailable' then raise;end if;end;
 perform pg_temp.check((select state='running' and result='{}' from public.brand_research_runs where id=q),'history failure rolls back research completion');
end$$;
select count(*) as passed from checks;
ROLLBACK;
